#define ASSERT_TRUE(cond)                                                     \
  do {                                                                        \
    if (!(cond)) {                                                            \
      fprintf(stderr, "ASSERT_TRUE failed at %s:%d: %s\n", __FILE__,          \
              __LINE__, #cond);                                               \
      std::exit(1);                                                           \
    }                                                                         \
  } while (0)

#define ASSERT_EQ(expected, actual)                                           \
  do {                                                                        \
    auto _exp = (expected);                                                   \
    auto _act = (actual);                                                     \
    if (!(_exp == _act)) {                                                    \
      fprintf(stderr, "ASSERT_EQ failed at %s:%d: %s != %s\n", __FILE__,      \
              __LINE__, #expected, #actual);                                  \
      std::exit(1);                                                           \
    }                                                                         \
  } while (0)

#define EXPECT_EQ(expected, actual) ASSERT_EQ(expected, actual)

#define ASSERT_NE(expected, actual)                                           \
  do {                                                                        \
    auto _exp = (expected);                                                   \
    auto _act = (actual);                                                     \
    if (!(_exp != _act)) {                                                    \
      fprintf(stderr, "ASSERT_NE failed at %s:%d: %s == %s\n", __FILE__,      \
              __LINE__, #expected, #actual);                                  \
      std::exit(1);                                                           \
    }                                                                         \
  } while (0)

#define EXPECT_NE(expected, actual) ASSERT_NE(expected, actual)

#define EXPECT_GT(val, bound)                                                 \
  do {                                                                        \
    auto _v = (val);                                                          \
    auto _b = (bound);                                                        \
    if (!(_v > _b)) {                                                         \
      fprintf(stderr, "EXPECT_GT failed at %s:%d: %s <= %s\n", __FILE__,      \
              __LINE__, #val, #bound);                                        \
      std::exit(1);                                                           \
    }                                                                         \
  } while (0)

namespace {

constexpr int kSdWidth = 640;
constexpr int kSdHeight = 480;
constexpr int kNumLoopbackFrames = 15;

void FillMovingI420Frame(std::vector<uint8_t>& y_plane,
                         std::vector<uint8_t>& u_plane,
                         std::vector<uint8_t>& v_plane, int width, int height,
                         int frame_idx) {
  const int box_x = (32 + frame_idx * 12) % (width - 80);
  const int box_y = (24 + frame_idx * 8) % (height - 80);
  for (int y = 0; y < height; ++y) {
    for (int x = 0; x < width; ++x) {
      if (x >= box_x && x < box_x + 80 && y >= box_y && y < box_y + 80) {
        y_plane[y * width + x] = 220;
      } else {
        int val = 32 + (((x + frame_idx * 6) + (y + frame_idx * 4)) % 160);
        y_plane[y * width + x] = static_cast<uint8_t>(val);
      }
    }
  }
  const int uv_w = width / 2;
  const int uv_h = height / 2;
  for (int cy = 0; cy < uv_h; ++cy) {
    for (int cx = 0; cx < uv_w; ++cx) {
      u_plane[cy * uv_w + cx] =
          static_cast<uint8_t>(64 + ((cx + frame_idx * 3) % 128));
      v_plane[cy * uv_w + cx] =
          static_cast<uint8_t>(64 + ((cy + frame_idx * 3) % 128));
    }
  }
}

double PlanePsnr(const uint8_t* src, int src_stride, const uint8_t* decoded,
                 int dec_stride, int width, int height) {
  uint64_t sse = 0;
  for (int y = 0; y < height; ++y) {
    const uint8_t* s_row = src + static_cast<size_t>(y) * src_stride;
    const uint8_t* d_row = decoded + static_cast<size_t>(y) * dec_stride;
    for (int x = 0; x < width; ++x) {
      int diff = static_cast<int>(s_row[x]) - static_cast<int>(d_row[x]);
      sse += static_cast<uint64_t>(diff * diff);
    }
  }
  if (sse == 0) {
    return 99.0;
  }
  double mse = static_cast<double>(sse) / static_cast<double>(width * height);
  return 10.0 * std::log10((255.0 * 255.0) / mse);
}

void TestVersionAndCapability() {
  OpenH264Version ver = WelsGetCodecVersion();
  EXPECT_EQ(2u, ver.uMajor);
  EXPECT_EQ(6u, ver.uMinor);
  EXPECT_EQ(0u, ver.uRevision);

  OpenH264Version ver_ex{};
  WelsGetCodecVersionEx(&ver_ex);
  EXPECT_EQ(2u, ver_ex.uMajor);
  EXPECT_EQ(6u, ver_ex.uMinor);
  EXPECT_EQ(0u, ver_ex.uRevision);

  SDecoderCapability cap{};
  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            WelsGetDecoderCapability(&cap));
  EXPECT_EQ(66, cap.iProfileIdc);
  EXPECT_EQ(32, cap.iLevelIdc);
}

void TestEncoderLifecycleAndMethods() {
  ISVCEncoder* encoder = nullptr;
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            WelsCreateSVCEncoder(&encoder));
  ASSERT_NE(nullptr, encoder);

  SEncParamExt param{};
  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->GetDefaultParams(&param));

  const int width = kSdWidth;
  const int height = kSdHeight;
  param.iPicWidth = width;
  param.iPicHeight = height;
  param.fMaxFrameRate = 30.0f;
  param.iTargetBitrate = 2000000;
  param.sSpatialLayers[0].iVideoWidth = width;
  param.sSpatialLayers[0].iVideoHeight = height;
  param.sSpatialLayers[0].fFrameRate = 30.0f;
  param.sSpatialLayers[0].iSpatialBitrate = 2000000;
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->InitializeExt(&param));

  int trace_level = static_cast<int>(WelsLogLevel::WELS_LOG_QUIET);
  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->SetOption(ENCODER_OPTION::ENCODER_OPTION_TRACE_LEVEL,
                               reinterpret_cast<c_void*>(&trace_level)));

  int idr_interval = -1;
  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->GetOption(ENCODER_OPTION::ENCODER_OPTION_IDR_INTERVAL,
                               reinterpret_cast<c_void*>(&idr_interval)));

  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->ForceIntraFrame(true, -1));

  SFrameBSInfo ps_info{};
  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->EncodeParameterSets(&ps_info));
  EXPECT_GT(ps_info.iLayerNum, 0);

  std::vector<uint8_t> y_plane(width * height);
  std::vector<uint8_t> u_plane((width / 2) * (height / 2));
  std::vector<uint8_t> v_plane((width / 2) * (height / 2));
  FillMovingI420Frame(y_plane, u_plane, v_plane, width, height, 0);

  SSourcePicture src_pic{};
  src_pic.iColorFormat =
      static_cast<int32_t>(EVideoFormatType::videoFormatI420);
  src_pic.iPicWidth = width;
  src_pic.iPicHeight = height;
  src_pic.iStride[0] = width;
  src_pic.iStride[1] = width / 2;
  src_pic.iStride[2] = width / 2;
  src_pic.pData[0] = y_plane.data();
  src_pic.pData[1] = u_plane.data();
  src_pic.pData[2] = v_plane.data();

  SFrameBSInfo bs_info{};
  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->EncodeFrame(&src_pic, &bs_info));
  EXPECT_EQ(EVideoFrameType::videoFrameTypeIDR, bs_info.eFrameType);
  EXPECT_GT(bs_info.iLayerNum, 0);

  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->Uninitialize());

  // Re-initialize using SEncParamBase via Initialize()
  SEncParamBase base_param{};
  base_param.iUsageType = EUsageType::CAMERA_VIDEO_REAL_TIME;
  base_param.iPicWidth = width;
  base_param.iPicHeight = height;
  base_param.fMaxFrameRate = 30.0f;
  base_param.iTargetBitrate = 2000000;
  encoder->SetOption(ENCODER_OPTION::ENCODER_OPTION_TRACE_LEVEL,
                     reinterpret_cast<c_void*>(&trace_level));
  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->Initialize(&base_param));
  EXPECT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->Uninitialize());

  WelsDestroySVCEncoder(encoder);
}

void TestEncodeAndDecodeLoopback() {
  const int width = kSdWidth;
  const int height = kSdHeight;

  ISVCEncoder* encoder = nullptr;
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            WelsCreateSVCEncoder(&encoder));

  int trace_level = static_cast<int>(WelsLogLevel::WELS_LOG_QUIET);
  encoder->SetOption(ENCODER_OPTION::ENCODER_OPTION_TRACE_LEVEL,
                     reinterpret_cast<c_void*>(&trace_level));

  SEncParamExt param{};
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->GetDefaultParams(&param));
  param.iPicWidth = width;
  param.iPicHeight = height;
  param.fMaxFrameRate = 30.0f;
  param.iTargetBitrate = 2500000;
  param.iMaxBitrate = 2500000;
  param.bEnableFrameSkip = false;
  param.sSpatialLayers[0].iVideoWidth = width;
  param.sSpatialLayers[0].iVideoHeight = height;
  param.sSpatialLayers[0].fFrameRate = 30.0f;
  param.sSpatialLayers[0].iSpatialBitrate = 2500000;
  param.sSpatialLayers[0].iMaxSpatialBitrate = 2500000;
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->InitializeExt(&param));

  std::vector<uint8_t> y_plane(width * height);
  std::vector<uint8_t> u_plane((width / 2) * (height / 2));
  std::vector<uint8_t> v_plane((width / 2) * (height / 2));

  SSourcePicture src_pic{};
  src_pic.iColorFormat =
      static_cast<int32_t>(EVideoFormatType::videoFormatI420);
  src_pic.iPicWidth = width;
  src_pic.iPicHeight = height;
  src_pic.iStride[0] = width;
  src_pic.iStride[1] = width / 2;
  src_pic.iStride[2] = width / 2;
  src_pic.pData[0] = y_plane.data();
  src_pic.pData[1] = u_plane.data();
  src_pic.pData[2] = v_plane.data();

  std::vector<std::vector<uint8_t>> frames;
  frames.reserve(kNumLoopbackFrames);
  for (int f = 0; f < kNumLoopbackFrames; ++f) {
    FillMovingI420Frame(y_plane, u_plane, v_plane, width, height, f);
    src_pic.uiTimeStamp = f * 33;
    SFrameBSInfo bs_info{};
    ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
              encoder->EncodeFrame(&src_pic, &bs_info));
    if (f == 0) {
      EXPECT_EQ(EVideoFrameType::videoFrameTypeIDR, bs_info.eFrameType);
    } else {
      EXPECT_EQ(EVideoFrameType::videoFrameTypeP, bs_info.eFrameType);
    }
    std::vector<uint8_t> bitstream;
    for (int i = 0; i < bs_info.iLayerNum; ++i) {
      const SLayerBSInfo& layer = bs_info.sLayerInfo[i];
      int layer_len = 0;
      for (int j = 0; j < layer.iNalCount; ++j) {
        layer_len += layer.pNalLengthInByte[j];
      }
      bitstream.insert(bitstream.end(), layer.pBsBuf, layer.pBsBuf + layer_len);
    }
    EXPECT_GT(bitstream.size(), 0u);
    frames.push_back(std::move(bitstream));
  }

  encoder->Uninitialize();
  WelsDestroySVCEncoder(encoder);

  // Decode all SD frames via ISVCDecoder and verify PSNR and motion
  ISVCDecoder* decoder = nullptr;
  ASSERT_EQ(static_cast<ptrdiff_t>(CM_RETURN::cmResultSuccess),
            WelsCreateDecoder(&decoder));
  ASSERT_NE(nullptr, decoder);

  SDecodingParam dec_param{};
  dec_param.sVideoProperty.eVideoBsType =
      VIDEO_BITSTREAM_TYPE::VIDEO_BITSTREAM_SVC;
  ASSERT_EQ(static_cast<ptrdiff_t>(CM_RETURN::cmResultSuccess),
            decoder->Initialize(&dec_param));

  EXPECT_EQ(static_cast<ptrdiff_t>(CM_RETURN::cmResultSuccess),
            decoder->SetOption(DECODER_OPTION::DECODER_OPTION_TRACE_LEVEL,
                               reinterpret_cast<c_void*>(&trace_level)));

  int eos = 0;
  EXPECT_EQ(static_cast<ptrdiff_t>(CM_RETURN::cmResultSuccess),
            decoder->GetOption(DECODER_OPTION::DECODER_OPTION_END_OF_STREAM,
                               reinterpret_cast<c_void*>(&eos)));
  EXPECT_EQ(0, eos);

  std::vector<uint8_t> prev_decoded_y(width * height);

  for (int f = 0; f < kNumLoopbackFrames; ++f) {
    unsigned char* dst[3] = {nullptr, nullptr, nullptr};
    SBufferInfo buf_info{};
    int32_t state = 0;
    if (f + 1 < kNumLoopbackFrames) {
      state = decoder->DecodeFrameNoDelay(
          frames[f].data(), static_cast<int>(frames[f].size()), dst, &buf_info);
      EXPECT_EQ(static_cast<int32_t>(DECODING_STATE::dsErrorFree), state);
    } else {
      state = decoder->DecodeFrame2(
          frames[f].data(), static_cast<int>(frames[f].size()), dst, &buf_info);
      EXPECT_EQ(static_cast<int32_t>(DECODING_STATE::dsErrorFree), state);
      int end_of_stream = 1;
      decoder->SetOption(DECODER_OPTION::DECODER_OPTION_END_OF_STREAM,
                         reinterpret_cast<c_void*>(&end_of_stream));
      if (buf_info.iBufferStatus != 1) {
        state = decoder->DecodeFrame2(nullptr, 0, dst, &buf_info);
        EXPECT_EQ(static_cast<int32_t>(DECODING_STATE::dsErrorFree), state);
      }
      if (buf_info.iBufferStatus != 1) {
        state = decoder->FlushFrame(dst, &buf_info);
        EXPECT_EQ(static_cast<int32_t>(DECODING_STATE::dsErrorFree), state);
      }
    }
    EXPECT_EQ(1, buf_info.iBufferStatus);
    EXPECT_EQ(width, buf_info.UsrData.sSystemBuffer.iWidth);
    EXPECT_EQ(height, buf_info.UsrData.sSystemBuffer.iHeight);
    EXPECT_NE(nullptr, dst[0]);
    EXPECT_NE(nullptr, dst[1]);
    EXPECT_NE(nullptr, dst[2]);

    FillMovingI420Frame(y_plane, u_plane, v_plane, width, height, f);
    int y_stride = buf_info.UsrData.sSystemBuffer.iStride[0];
    int uv_stride = buf_info.UsrData.sSystemBuffer.iStride[1];
    double psnr_y =
        PlanePsnr(y_plane.data(), width, dst[0], y_stride, width, height);
    double psnr_u = PlanePsnr(u_plane.data(), width / 2, dst[1], uv_stride,
                              width / 2, height / 2);
    double psnr_v = PlanePsnr(v_plane.data(), width / 2, dst[2], uv_stride,
                              width / 2, height / 2);
    ASSERT_TRUE(psnr_y >= 30.0);
    ASSERT_TRUE(psnr_u >= 30.0);
    ASSERT_TRUE(psnr_v >= 30.0);

    if (f > 0) {
      bool diff_found = false;
      for (int row = 0; row < height; ++row) {
        if (std::memcmp(prev_decoded_y.data() + static_cast<size_t>(row) * width,
                        dst[0] + static_cast<size_t>(row) * y_stride,
                        width) != 0) {
          diff_found = true;
          break;
        }
      }
      ASSERT_TRUE(diff_found);
    }
    for (int row = 0; row < height; ++row) {
      std::memcpy(prev_decoded_y.data() + static_cast<size_t>(row) * width,
                  dst[0] + static_cast<size_t>(row) * y_stride, width);
    }
  }

  EXPECT_EQ(static_cast<ptrdiff_t>(CM_RETURN::cmResultSuccess),
            decoder->Uninitialize());
  WelsDestroyDecoder(decoder);
}

void TestDecodeParserMode() {
  const int width = kSdWidth;
  const int height = kSdHeight;

  ISVCEncoder* encoder = nullptr;
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            WelsCreateSVCEncoder(&encoder));

  SEncParamExt param{};
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->GetDefaultParams(&param));
  param.iPicWidth = width;
  param.iPicHeight = height;
  param.fMaxFrameRate = 30.0f;
  param.iTargetBitrate = 2000000;
  param.sSpatialLayers[0].iVideoWidth = width;
  param.sSpatialLayers[0].iVideoHeight = height;
  param.sSpatialLayers[0].fFrameRate = 30.0f;
  param.sSpatialLayers[0].iSpatialBitrate = 2000000;
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->InitializeExt(&param));

  int trace_level = static_cast<int>(WelsLogLevel::WELS_LOG_QUIET);
  encoder->SetOption(ENCODER_OPTION::ENCODER_OPTION_TRACE_LEVEL,
                     reinterpret_cast<c_void*>(&trace_level));

  std::vector<uint8_t> y_plane(width * height);
  std::vector<uint8_t> u_plane((width / 2) * (height / 2));
  std::vector<uint8_t> v_plane((width / 2) * (height / 2));
  FillMovingI420Frame(y_plane, u_plane, v_plane, width, height, 0);

  SSourcePicture src_pic{};
  src_pic.iColorFormat =
      static_cast<int32_t>(EVideoFormatType::videoFormatI420);
  src_pic.iPicWidth = width;
  src_pic.iPicHeight = height;
  src_pic.iStride[0] = width;
  src_pic.iStride[1] = width / 2;
  src_pic.iStride[2] = width / 2;
  src_pic.pData[0] = y_plane.data();
  src_pic.pData[1] = u_plane.data();
  src_pic.pData[2] = v_plane.data();

  SFrameBSInfo bs_info{};
  ASSERT_EQ(static_cast<int32_t>(CM_RETURN::cmResultSuccess),
            encoder->EncodeFrame(&src_pic, &bs_info));

  std::vector<uint8_t> bitstream;
  for (int i = 0; i < bs_info.iLayerNum; ++i) {
    const SLayerBSInfo& layer = bs_info.sLayerInfo[i];
    int layer_len = 0;
    for (int j = 0; j < layer.iNalCount; ++j) {
      layer_len += layer.pNalLengthInByte[j];
    }
    bitstream.insert(bitstream.end(), layer.pBsBuf, layer.pBsBuf + layer_len);
  }

  encoder->Uninitialize();
  WelsDestroySVCEncoder(encoder);

  ISVCDecoder* parser = nullptr;
  ASSERT_EQ(static_cast<ptrdiff_t>(CM_RETURN::cmResultSuccess),
            WelsCreateDecoder(&parser));
  SDecodingParam parse_param{};
  parse_param.bParseOnly = true;
  parse_param.sVideoProperty.eVideoBsType =
      VIDEO_BITSTREAM_TYPE::VIDEO_BITSTREAM_SVC;
  ASSERT_EQ(static_cast<ptrdiff_t>(CM_RETURN::cmResultSuccess),
            parser->Initialize(&parse_param));
  parser->SetOption(DECODER_OPTION::DECODER_OPTION_TRACE_LEVEL,
                    reinterpret_cast<c_void*>(&trace_level));

  SParserBsInfo parser_info{};
  int32_t state = parser->DecodeParser(
      bitstream.data(), static_cast<int>(bitstream.size()), &parser_info);
  EXPECT_EQ(static_cast<int32_t>(DECODING_STATE::dsErrorFree), state);

  parser_info = {};
  state = parser->DecodeParser(nullptr, 0, &parser_info);
  EXPECT_EQ(static_cast<int32_t>(DECODING_STATE::dsErrorFree), state);
  EXPECT_GT(parser_info.iNalNum, 0);

  EXPECT_EQ(static_cast<ptrdiff_t>(CM_RETURN::cmResultSuccess),
            parser->Uninitialize());
  WelsDestroyDecoder(parser);
}

}  // namespace

int main() {
  TestVersionAndCapability();
  TestEncoderLifecycleAndMethods();
  TestEncodeAndDecodeLoopback();
  TestDecodeParserMode();
  std::printf("cxx_api_test: all 4 tests passed\n");
  return 0;
}
